   "n": "Этап проектирования RUS_Stage",
   "what": "Проверяет у элементов атрибут RUS_Stage — номер этапа проектирования; если этапов нет, должна стоять 1.",
   "d": "Если объект делится на этапы проектирования, у элементов зданий ЦИМ АР RUS_Stage заполнен порядковым номером этапа; если этапов нет — значение 1.",
